CREATE TABLE exercise (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description VARCHAR(1000) NOT NULL,
    muscle VARCHAR(60) NOT NULL,
    difficulty VARCHAR(20) NOT NULL CHECK(difficulty IN ('Principiante','Intermedio','Avanzado')),
    equipment VARCHAR(100) NOT NULL,
    image VARCHAR(1000) NOT NULL DEFAULT '',
    icon VARCHAR(50) NOT NULL DEFAULT 'bi-activity',
    default_sets INTEGER NOT NULL CHECK(default_sets BETWEEN 1 AND 20),
    default_reps INTEGER NOT NULL CHECK(default_reps BETWEEN 1 AND 100),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    version BIGINT NOT NULL DEFAULT 0
);
CREATE UNIQUE INDEX exercise_name_idx ON exercise (normalize(casefold(normalize(name,NFC) COLLATE pg_catalog.pg_unicode_fast),NFC));
CREATE TABLE training_routine (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owner_id BIGINT NOT NULL REFERENCES app_user(id),
    name VARCHAR(100) NOT NULL CHECK(length(trim(name)) > 0),
    version BIGINT NOT NULL DEFAULT 0 CHECK(version >= 0),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);
CREATE UNIQUE INDEX routine_owner_name_idx ON training_routine (owner_id,normalize(casefold(normalize(name,NFC) COLLATE pg_catalog.pg_unicode_fast),NFC));
CREATE TABLE routine_exercise (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    routine_id BIGINT NOT NULL REFERENCES training_routine(id) ON DELETE CASCADE,
    exercise_id BIGINT NOT NULL REFERENCES exercise(id),
    sets INTEGER NOT NULL CHECK(sets BETWEEN 1 AND 20),
    reps INTEGER NOT NULL CHECK(reps BETWEEN 1 AND 100),
    UNIQUE(routine_id,exercise_id)
);
